/**
 * Concise column headings — the shared extension of lib/i18n/table-headers.ts (merged into HEADER_TRANSLATIONS at import time).
 *   - HEADER_EXTRA: five-language rows (English key → ur / ar / fa / ps) for headings that had no entry, and SHORTER replacements
 *     for headings whose translation was long. Values are short on purpose so a heading fits on one line.
 *   - HEADER_EN_SHORT: concise English text for English headings that were overly long (meaning unchanged).
 * Only the heading LABEL changes: column values, names, columns and functionality are untouched. Keys are the English heading,
 * upper-cased (see normalize() in table-headers.ts); a trailing sort arrow (↕ ⇅ ↓ ↑) is ignored when looking a heading up.
 */
type Row = { ur: string; ar: string; fa: string; ps: string };
